/* Classroom archive and study tools. Uses the existing authenticated backend. */
let studioOwner=accountUserId||'guest',studioId=crypto.randomUUID(),studioCreated=new Date().toISOString(),studioView='classroom',studioAudio=null,studioAudioUrl=null,studioCheckpointTimer=null,studioCloudRows=[],studioNotes='',studioCardIndex=0,studioCardFlipped=false,studioSaving=false,studioStorageWarned=false,studioAudioNonce=0,studioOpenNonce=0,studioStarting=false,studioPausedAt=0;
const studioKey=()=>`lc_studio_${studioOwner}`;
const serializedItems=()=>items.map(x=>({text:String(x.text||''),translation:String(x.translation||''),time:x.time||'00:00',lang:x.lang||'英语',code:x.code||$('source').value,bookmarked:!!x.bookmarked,user_corrected:!!x.user_corrected}));
function localRecords(){try{const rows=JSON.parse(localStorage.getItem(studioKey())||'[]');return Array.isArray(rows)?rows:[]}catch{return []}}
function snapshotClass(){return {id:studioId,cloudId:currentCloudId,title:($('title').value||'未命名课堂').slice(0,200),created_at:studioCreated,updated_at:new Date().toISOString(),language:$('source').value,target:$('target').value,transcript:serializedItems(),summary:summaryData,notes:$('personalNotes').value,duration:$('duration').textContent,hasAudio:!!studioAudio}}
function archiveCurrent(){if(!items.length&&!$('personalNotes').value.trim()&&!studioAudio)return;try{const row=snapshotClass();const rows=localRecords();const index=rows.findIndex(x=>x.id===row.id);if(index<0)rows.unshift(row);else rows[index]=row;localStorage.setItem(studioKey(),JSON.stringify(rows));$('draftStatus').textContent='课堂记录已保存到本机 · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});}catch{$('draftStatus').textContent='本机存储不足，请导出备份';if(!studioStorageWarned){studioStorageWarned=true;toast('本机文字保存失败，请导出课堂备份。')}}}
function queueCheckpoint(){clearTimeout(studioCheckpointTimer);studioCheckpointTimer=setTimeout(archiveCurrent,600)}
function audioDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('lc-studio-audio',1);req.onupgradeneeded=()=>req.result.createObjectStore('recordings');req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result)})}
async function storeAudio(owner,id,blob){const db=await audioDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('recordings','readwrite');tx.objectStore('recordings').put(blob,owner+':'+id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}finally{db.close()}}
async function readAudio(owner,id){const db=await audioDB();try{return await new Promise((resolve,reject)=>{const req=db.transaction('recordings').objectStore('recordings').get(owner+':'+id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}finally{db.close()}}
async function removeAudio(owner,id){const db=await audioDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('recordings','readwrite');tx.objectStore('recordings').delete(owner+':'+id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}finally{db.close()}}
function attachAudio(blob){const player=$('audioPlayer');if(player){player.pause();player.removeAttribute('src');player.load()}if(studioAudioUrl){URL.revokeObjectURL(studioAudioUrl);studioAudioUrl=null}studioAudio=blob||null;if(blob){studioAudioUrl=URL.createObjectURL(blob);if(player){player.src=studioAudioUrl;$('audioShelf').classList.remove('hidden');$('saveAudio').disabled=false}}else{$('audioShelf').classList.add('hidden');$('saveAudio').disabled=true}}
function seekAudio(time){if(active)return toast('课堂结束后可以回听录音。');if(!studioAudio)return toast('本设备没有这堂课的录音，可从录音所在设备打开。');const sec=parseTime(time);$('audioPlayer').currentTime=sec;$('audioPlayer').play().catch(()=>toast('请点击录音播放按钮开始回听。'))}
function parseTime(value){const parts=String(value||'00:00').split(':').map(Number);return parts.length===3?parts[0]*3600+parts[1]*60+parts[2]:parts[0]*60+(parts[1]||0)}
function showView(view){if(!['classroom','library','glossary','documents'].includes(view))return;studioView=view;for(const name of ['classroom','library','glossary','documents'])$(name+'View').classList.toggle('hidden',name!==view);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('recordDock').classList.toggle('hidden',view!=='classroom');$('viewCrumb').textContent='学习空间 / '+({classroom:'课堂',library:'我的课堂',glossary:'个人术语',documents:'文件学习'}[view]);if(view==='library'){archiveCurrent();renderLibrary();refreshCloudLibrary()}if(view==='glossary')renderGlossary();}
