render=function(){const stream=$('stream'),query=$('transcriptSearch').value.trim().toLocaleLowerCase(),mode=$('displayMode').value;const visible=items.map((x,i)=>({x,i})).filter(({x})=>!query||[x.text,x.translation].some(v=>String(v||'').toLocaleLowerCase().includes(query)));stream.querySelectorAll('.entry,.interim-entry,.no-results').forEach(n=>n.remove());$('empty').classList.toggle('hidden',items.length>0||!!(active&&!paused&&window.interimText));const fragment=document.createDocumentFragment();for(const {x,i} of visible){const d=document.createElement('article');d.className='entry'+(x.bookmarked?' bookmarked':'');d.innerHTML=`<div class="entrytop"><div><button class="time-button" data-seek="${i}" aria-label="回听 ${escapeHtml(x.time)}">${escapeHtml(x.time)}</button><span class="pill">${escapeHtml(x.lang)}</span></div><div class="entry-actions"><button data-star="${i}" class="${x.bookmarked?'starred':''}" aria-pressed="${!!x.bookmarked}" aria-label="${x.bookmarked?'取消重点':'标记重点'}">${x.bookmarked?'★ 已标记':'☆ 重点'}</button>${x.translation?.startsWith('（翻译暂')&&!x._translating?`<button data-retry="${i}">重试翻译</button>`:''}</div></div>${mode!=='translation'?`<div class="en">${escapeHtml(x.text)}</div>`:''}${mode!=='original'?`<div class="zh ${x.translation&&!x.translation.startsWith('（翻译暂')?'':'pending'}">${x.translation?escapeHtml(x.translation):'正在翻译…'}</div>`:''}<details><summary>修正译文</summary><div class="correction-row"><input class="fix-input" data-index="${i}" aria-label="修正第 ${i+1} 条译文" value="${escapeHtml(x.translation||'')}"><button class="btn" data-fix="${i}">保存修正</button></div></details>`;fragment.append(d)}if(items.length&&!visible.length){const d=document.createElement('p');d.className='no-results';d.textContent='没有找到匹配的原文或译文。';fragment.append(d)}if(active&&!paused&&!query&&window.interimText){const d=document.createElement('article');d.className='entry interim-entry';d.innerHTML='<div class="pill">初稿 · 正在修订</div><div class="en pending">'+escapeHtml(window.interimText)+'</div><p class="sub">确认后更新为稳定字幕并翻译；初稿不计入笔记。</p>';fragment.append(d)}stream.append(fragment);stream.querySelectorAll('[data-seek]').forEach(b=>b.onclick=()=>seekAudio(items[Number(b.dataset.seek)].time));stream.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{const x=items[Number(b.dataset.star)];x.bookmarked=!x.bookmarked;render();renderBookmarks()});stream.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{const x=items[Number(b.dataset.retry)];if(!x||x._translating)return;x.translation='';translate(x);render()});stream.querySelectorAll('[data-fix]').forEach(b=>b.onclick=async()=>{const x=items[Number(b.dataset.fix)],value=stream.querySelector(`[data-index="${b.dataset.fix}"]`).value.trim();if(!value)return toast('请输入修正译文。');if(cloudAuthed&&x.text.length<=180&&value.length<=300)await saveGlossary(x,value);else{x.translation=value;x.user_corrected=true;render();toast('译文已在本堂课中修正；登录后可保存短语到个人术语。')}});if($('autoScroll').checked&&!query)stream.scrollTop=stream.scrollHeight;updateCount();renderBookmarks();queueCheckpoint();syncDock()};
function renderBookmarks(){const marked=items.filter(x=>x.bookmarked);$('bookmarkList').innerHTML=marked.length?marked.map(x=>`<div class="bookmark-item"><button data-time="${escapeHtml(x.time)}">${escapeHtml(x.time)} · 回听</button><div>${escapeHtml(x.translation||x.text)}</div></div>`).join(''):'<p class="sub">点击字幕旁的“☆ 重点”，复习时更容易找到。</p>';$('bookmarkList').querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>seekAudio(b.dataset.time))}
$('transcriptSearch').oninput=render;$('displayMode').onchange=render;
$('personalNotes').oninput=queueCheckpoint;$('title').oninput=queueCheckpoint;
$('focusMode').onclick=()=>{const yes=document.body.classList.toggle('focus-classroom');$('focusMode').setAttribute('aria-pressed',String(yes));$('focusMode').textContent=yes?'退出专注':'专注'};
$('playbackRate').onchange=()=>{$('audioPlayer').playbackRate=Number($('playbackRate').value)};
