const originalStart=start,originalStop=stop;
start=async function(){if(active||studioStarting)return;const issue=recordingCheck();if(issue){reliabilityNotice(issue);toast(issue);return}const startingOwner=studioOwner;studioStarting=true;$('start').disabled=true;let preparedStream;try{preparedStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}})}catch(error){studioStarting=false;$('start').disabled=false;const message=error.name==='NotAllowedError'?'麦克风权限未开启，请在浏览器中允许访问后重试。':'无法连接麦克风，请检查设备后重试。';reliabilityNotice(message);toast(message);return}if(startingOwner!==studioOwner){preparedStream.getTracks().forEach(track=>track.stop());studioStarting=false;$('start').disabled=false;reliabilityNotice('账户已更换，请重新开始课堂。');return}archiveCurrent();clearTimeout(studioCheckpointTimer);++studioOpenNonce;++studioAudioNonce;studioId=crypto.randomUUID();studioCreated=new Date().toISOString();attachAudio(null);studioNotes='';$('personalNotes').value='';paused=false;const owner=studioOwner,id=studioId;await originalStart(preparedStream);studioStarting=false;$('start').disabled=false;syncDock();if(active&&recorder){const record=recorder,parts=chunks;reliabilityNotice('课堂已开始。请保持页面前台；录音结束后保存到本机，云端课堂目前保存文字笔记。');record.addEventListener('stop',async()=>{const blob=new Blob(parts,{type:record.mimeType||'audio/webm'});if(studioOwner===owner&&studioId===id){attachAudio(blob);archiveCurrent()}try{await storeAudio(owner,id,blob);if(studioOwner===owner&&studioId===id)reliabilityNotice('录音已保存到本机，可回听或下载。云端课堂保存文字笔记，录音仍在这台设备。')}catch{if(studioOwner===owner&&studioId===id){reliabilityNotice('本机录音存储失败，录音仅在当前页面可用。请立即下载录音，关闭页面可能丢失。');toast('录音仅在当前页面可用，请下载保存；本机录音存储失败。')}}})}};
