$('start').onclick=start;$('stop').onclick=stop;
$('pauseClass').onclick=()=>{if(!active)return;paused=!paused;if(paused){studioPausedAt=Date.now();clearInterval(timer);if(recognition)recognition._captionClosing=true;try{recognition?.stop()}catch{}if(recorder?.state==='recording')recorder.pause();$('liveText').textContent='课堂已暂停';$('recState').textContent='已暂停';window.interimText=''}else{startedAt+=Date.now()-studioPausedAt;timer=setInterval(()=>$('duration').textContent=fmt(Math.floor((Date.now()-startedAt)/1000)),1000);if(recorder?.state==='paused')recorder.resume();try{recognition?.start()}catch{}$('liveText').textContent='正在录音';$('recState').textContent='录音中'}syncDock();render()};
