const originalStopWithPaused=stop;stop=function(){if(recorder?.state==='paused')recorder.resume();originalStopWithPaused()};$('stop').onclick=stop;
$('newClass').onclick=()=>{if(active||studioStarting)return toast('请先结束当前课堂或等待麦克风启动完成。');archiveCurrent();clearTimeout(studioCheckpointTimer);++studioOpenNonce;++studioAudioNonce;studioId=crypto.randomUUID();studioCreated=new Date().toISOString();items=[];summaryData=null;currentCloudId=null;qualityRun=null;studioNotes='';$('personalNotes').value='';$('title').value='';$('duration').textContent='00:00';$('sessionLabel').textContent='选择授课语言，点击下方开始课堂';$('liveText').textContent='准备开始';$('summaryBox').classList.add('hidden');document.querySelector('.assistant-intro').classList.remove('hidden');attachAudio(null);render();renderReview();showStudy('summary');showView('classroom')};
const originalShowSummary=showSummary;showSummary=function(x){originalShowSummary(x);document.querySelector('.assistant-intro').classList.add('hidden');studioCardIndex=0;studioCardFlipped=false;renderReview();queueCheckpoint()};
function safeSummary(x){if(!x||typeof x!=='object')return null;const strings=v=>Array.isArray(v)?v.filter(t=>typeof t==='string').slice(0,100).map(t=>t.slice(0,5000)):[];return{overview:typeof x.overview==='string'?x.overview.slice(0,15000):'',key_points:strings(x.key_points),key_terms:Array.isArray(x.key_terms)?x.key_terms.filter(t=>t&&typeof t.term==='string'&&typeof t.explanation==='string').slice(0,100).map(t=>({term:t.term.slice(0,1000),explanation:t.explanation.slice(0,5000)})):[],review_questions:strings(x.review_questions),unclear_points:strings(x.unclear_points)}}
function renderReview(){const terms=Array.isArray(summaryData?.key_terms)?summaryData.key_terms:[],questions=Array.isArray(summaryData?.review_questions)?summaryData.review_questions:[];if(!terms.length&&!questions.length){$('reviewContent').innerHTML='<div class="review-empty">先生成课堂总结。这里会用总结中的术语制作翻转卡片，并列出复习问题。</div>';return}studioCardIndex=Math.min(studioCardIndex,Math.max(0,terms.length-1));const term=terms[studioCardIndex];$('reviewContent').innerHTML=(terms.length?`<h3 class="small-heading">术语闪卡</h3><button class="flashcard" id="flipCard"><span>${escapeHtml(studioCardFlipped?term.explanation:term.term)}<small>${studioCardFlipped?'点击回到术语':'点击查看解释'}</small></span></button><div class="flashcard-nav"><button id="prevCard" aria-label="上一张卡片">←</button><span>${studioCardIndex+1} / ${terms.length}</span><button id="nextCard" aria-label="下一张卡片">→</button></div>`:'')+(questions.length?'<h3 class="small-heading">复习自测</h3><p class="sub">问题取自本堂总结。你的作答仅保存到本机，不自动评分。</p>'+questions.map((q,i)=>`<div class="review-question"><label for="answer${i}">${i+1}. ${escapeHtml(q)}</label><textarea id="answer${i}" data-answer="${i}" placeholder="尝试用自己的话回答…"></textarea></div>`).join(''):'');if(term){$('flipCard').onclick=()=>{studioCardFlipped=!studioCardFlipped;renderReview()};$('prevCard').onclick=()=>{studioCardIndex=(studioCardIndex-1+terms.length)%terms.length;studioCardFlipped=false;renderReview()};$('nextCard').onclick=()=>{studioCardIndex=(studioCardIndex+1)%terms.length;studioCardFlipped=false;renderReview()}}$('reviewContent').querySelectorAll('[data-answer]').forEach(t=>{const key=studioKey()+'_answers_'+studioId+'_'+t.dataset.answer;t.value=localStorage.getItem(key)||'';t.oninput=()=>{try{localStorage.setItem(key,t.value.slice(0,5000))}catch{toast('本机存储不足，作答暂未保存。')}}})}
function renderLibrary(){const search=$('librarySearch').value.trim().toLocaleLowerCase(),scope=$('libraryScope').value;const local=localRecords().map(x=>({...x,kind:'local'})),cloud=studioCloudRows.map(x=>({...x,kind:'cloud'}));const rows=[...(scope==='cloud'?[]:local),...(scope==='local'?[]:cloud)].filter(x=>String(x.title||'').toLocaleLowerCase().includes(search));$('lectureList').innerHTML=rows.length?rows.map(x=>`<article class="lecture-card"><div class="row"><span class="source-tag">${x.kind==='cloud'?'云端笔记':'本机课堂'}</span>${x.kind==='local'?`<button class="text-btn" data-delete-local="${escapeHtml(x.id)}">删除本机副本</button>`:''}</div><h3>${escapeHtml(x.title||'未命名课堂')}</h3><p class="sub">${escapeHtml(new Date(x.created_at).toLocaleString())}</p><p class="sub">${x.kind==='local'?`${x.transcript?.length||0} 句 · ${x.hasAudio?'本机录音可回听':'文字记录'}`:'跨设备可访问 · 录音保留在原设备'}</p><button class="btn" data-open="${escapeHtml(x.id)}" data-kind="${x.kind}">打开课堂 →</button></article>`).join(''):'<div class="no-results">'+(search?'没有找到这门课。':'还没有课堂记录。开始一堂课后，文字会自动保存在本机。')+'</div>';$('lectureList').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openLecture(b.dataset.open,b.dataset.kind));$('lectureList').querySelectorAll('[data-delete-local]').forEach(b=>b.onclick=async()=>{if(!confirm('删除这堂课的本机文字和录音副本？云端笔记不会受影响。'))return;const id=b.dataset.deleteLocal,owner=studioOwner;if(studioId===id&&(active||studioStarting))return toast('请先结束当前课堂或等待麦克风启动完成。');++studioOpenNonce;++studioAudioNonce;try{await removeAudio(owner,id);if(owner!==studioOwner)return;localStorage.setItem(studioKey(),JSON.stringify(localRecords().filter(x=>x.id!==id)));if(studioId===id){items=[];summaryData=null;$('personalNotes').value='';currentCloudId=null;qualityRun=null;attachAudio(null);render();clearTimeout(studioCheckpointTimer)}renderLibrary()}catch{if(owner===studioOwner)toast('本机删除失败，请重试。')}})}
async function refreshCloudLibrary(){const owner=accountUserId;if(!supabaseClient||!owner){studioCloudRows=[];$('libraryStatus').textContent='登录后可以查看云端课堂；本机记录无需登录。';renderLibrary();return}$('libraryStatus').textContent='正在读取云端课堂…';const {data,error}=await supabaseClient.from('lectures').select('id,title,language,created_at').order('created_at',{ascending:false}).limit(100);if(owner!==accountUserId)return;if(error){$('libraryStatus').textContent='云端读取失败：'+error.message;return}studioCloudRows=data||[];$('libraryStatus').textContent='已载入最近 '+studioCloudRows.length+' 堂云端课堂。';renderLibrary()}
async function openLecture(id,kind){if(active||studioStarting)return toast('请先结束录音或等待麦克风启动完成，再打开另一堂课。');archiveCurrent();const owner=studioOwner,openNonce=++studioOpenNonce;let row;if(kind==='cloud'){const {data,error}=await supabaseClient.from('lectures').select('id,title,language,transcript,ai_summary,created_at').eq('id',id).single();if(error)return toast('课堂读取失败：'+error.message);if(owner!==studioOwner||openNonce!==studioOpenNonce)return;const match=localRecords().find(x=>x.cloudId===data.id);row={...data,id:match?.id||data.id,cloudId:data.id,summary:data.ai_summary,duration:match?.duration,target:match?.target};}else row=localRecords().find(x=>x.id===id);if(!row)return toast('这堂课已不存在。');if(owner!==studioOwner||openNonce!==studioOpenNonce)return;clearTimeout(studioCheckpointTimer);studioId=row.id;studioCreated=row.created_at;currentCloudId=row.cloudId||null;qualityRun=null;items=Array.isArray(row.transcript)?row.transcript.filter(x=>!x._meta):[];const meta=(row.transcript||[]).find(x=>x._meta);$('personalNotes').value=row.notes||meta?.notes||'';$('title').value=row.title;$('source').value=row.language||'en-US';if(row.target)$('target').value=row.target;applyPreferences();$('duration').textContent=row.duration||'00:00';$('sessionLabel').textContent='保存的课堂 · '+new Date(row.created_at).toLocaleString();$('liveText').textContent='课堂回顾';summaryData=row.summary||null;$('summaryBox').classList.toggle('hidden',!summaryData);document.querySelector('.assistant-intro').classList.toggle('hidden',!!summaryData);if(summaryData)showSummary(summaryData);else renderReview();const audioNonce=++studioAudioNonce;attachAudio(null);showView('classroom');render();try{const blob=await readAudio(owner,studioId);if(audioNonce===studioAudioNonce&&openNonce===studioOpenNonce&&owner===studioOwner&&studioId===row.id&&!active)attachAudio(blob)}catch{toast('本机录音暂时无法读取。')}}
$('refreshLibrary').onclick=refreshCloudLibrary;$('librarySearch').oninput=renderLibrary;$('libraryScope').onchange=renderLibrary;
saveCloud=async function(){if(studioSaving||!supabaseClient||!cloudAuthed||!items.length)return;studioSaving=true;const owner=accountUserId,id=studioId,existingId=currentCloudId,transcript=serializedItems();transcript.push({_meta:true,notes:$('personalNotes').value.slice(0,20000)});const row={user_id:owner,title:($('title').value||'课堂记录').slice(0,200),language:$('source').value,transcript,ai_summary:summaryData};$('cloudSave').disabled=true;$('cloudSave').textContent='正在保存…';try{let result;if(existingId)result=await supabaseClient.from('lectures').update(row).eq('id',existingId).select('id').single();else result=await supabaseClient.from('lectures').insert(row).select('id').single();if(result.error)throw result.error;if(owner===accountUserId&&id===studioId){currentCloudId=result.data.id;archiveCurrent();toast('课堂笔记与重点已保存到你的云端。')}studioCloudRows=[];}catch(e){toast('云端保存失败：'+e.message)}finally{studioSaving=false;$('cloudSave').textContent='保存到我的云端课堂';updateCount()}};
$('cloudSave').onclick=saveCloud;$('cloudLoad').onclick=()=>showView('library');
function downloadFile(text,type,suffix){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=($('title').value||'课堂记录').replace(/[\\/:*?"<>|]/g,'_')+suffix;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function srtTime(sec){const n=Math.max(0,Math.floor(sec));return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n/60)%60).padStart(2,'0')}:${String(n%60).padStart(2,'0')},000`}
$('saveNotes').onclick=()=>{const format=$('exportFormat').value;if(format==='json')return downloadFile(JSON.stringify({format:'lecture-companion-v1',...snapshotClass()},null,2),'application/json','.json');if(format==='srt'){const content=items.map((x,i)=>{const start=parseTime(x.time),next=i<items.length-1?parseTime(items[i+1].time):start+5;return `${i+1}\n${srtTime(start)} --> ${srtTime(Math.max(start+1,next))}\n${x.text}\n${x.translation||''}\n`}).join('\n');return downloadFile(content,'text/plain;charset=utf-8','.srt')}const content=[format==='md'?'# '+($('title').value||'课堂记录'):($('title').value||'课堂记录'),'','## 双语记录',...items.flatMap(x=>[`[${x.time}]${x.bookmarked?' ★ 重点':''} ${x.text}`,x.translation||'','']),...($('personalNotes').value?['## 我的笔记',$('personalNotes').value,'']:[]),...(summaryData?['## AI 总结',summaryData.overview||'','### 重点',...(summaryData.key_points||[]).map(x=>'- '+x),'### 核心术语',...(summaryData.key_terms||[]).map(x=>`- ${x.term}：${x.explanation}`),'### 复习问题',...(summaryData.review_questions||[]).map(x=>'- '+x)]:[])].join('\n');downloadFile('\ufeff'+content,'text/plain;charset=utf-8',format==='md'?'.md':'.txt')};
$('saveAudio').onclick=()=>{if(!studioAudio)return toast('本页面没有可下载的录音。');const a=document.createElement('a');a.href=studioAudioUrl;a.download=($('title').value||'课堂录音').replace(/[\\/:*?"<>|]/g,'_')+(studioAudio.type.includes('mp4')?'.m4a':studioAudio.type.includes('ogg')?'.ogg':'.webm');a.click()};
$('importBackup').onclick=()=>$('backupFile').click();$('backupFile').onchange=async()=>{const file=$('backupFile').files[0];$('backupFile').value='';if(!file)return;if(active)return toast('请先结束课堂再导入。');if(file.size>2*1024*1024)return toast('备份超过 2 MB，无法导入。');try{const row=JSON.parse(await file.text());if(row.format!=='lecture-companion-v1'||!Array.isArray(row.transcript)||row.transcript.length>1500)throw Error();if(!['en-US','en-GB','ms-MY'].includes(row.language))throw Error();const transcript=row.transcript.map(x=>{if(typeof x.text!=='string'||x.text.length>10000||typeof x.translation!=='string'||x.translation.length>15000)throw Error();return{text:x.text,translation:x.translation,time:/^\d{1,3}:\d{2}(?::\d{2})?$/.test(x.time)?x.time:'00:00',code:row.language,lang:row.language==='ms-MY'?'马来语':'英语',bookmarked:!!x.bookmarked}});archiveCurrent();const newRow={id:crypto.randomUUID(),title:String(row.title||'导入课堂').slice(0,200),language:row.language,transcript,notes:String(row.notes||'').slice(0,20000),created_at:new Date().toISOString(),summary:safeSummary(row.summary),hasAudio:false};localStorage.setItem(studioKey(),JSON.stringify([newRow,...localRecords()]));renderLibrary();toast('课堂文字备份已导入本机；未上传。')}catch{toast('备份格式无效或内容超出限制。')}};
function renderGlossary(){if(!cloudAuthed){$('glossaryList').innerHTML='<p class="sub">登录后可保存并同步你的个人术语。</p>';$('addTerm').disabled=true;return}$('addTerm').disabled=false;$('glossaryList').innerHTML=personalGlossary.length?personalGlossary.map((g,i)=>`<div class="glossary-row"><strong>${escapeHtml(g.source_term)}</strong><span>${escapeHtml(g.preferred_translation)}</span><button data-term="${i}" aria-label="删除术语 ${escapeHtml(g.source_term)}">删除</button></div>`).join(''):'<p class="sub">还没有个人术语。可以手动添加，也可以在字幕中保存修正。</p>';$('glossaryList').querySelectorAll('[data-term]').forEach(b=>b.onclick=async()=>{if(!confirm('删除这条个人术语？'))return;const g=personalGlossary[Number(b.dataset.term)];const {error}=await supabaseClient.from('glossary_terms').delete().eq('user_id',accountUserId).eq('source_language',g.source_language).eq('target_language',g.target_language).eq('source_term',g.source_term);if(error)return toast('删除失败：'+error.message);await refreshGlossary();renderGlossary()})}
$('glossaryForm').onsubmit=async e=>{e.preventDefault();if(!cloudAuthed)return toast('请先登录。');const row={user_id:accountUserId,source_language:$('source').value.startsWith('ms')?'ms':'en',target_language:$('target').value,source_term:$('termSource').value.trim(),preferred_translation:$('termTranslation').value.trim()};if(!row.source_term||!row.preferred_translation)return;const {error}=await supabaseClient.from('glossary_terms').upsert(row,{onConflict:'user_id,source_language,target_language,source_term'});if(error)return toast('保存失败：'+error.message);$('glossaryForm').reset();await refreshGlossary();renderGlossary();toast('术语已保存到你的个人账户。')};
function studioAccountChanged(){const next=accountUserId||'guest';$('connectionLabel').textContent=accountUserId?'账户已连接':'本机模式';if(next!==studioOwner){archiveCurrent();clearTimeout(studioCheckpointTimer);if(active)stop();studioOwner=next;++studioOpenNonce;++studioAudioNonce;studioId=crypto.randomUUID();studioCreated=new Date().toISOString();studioCloudRows=[];items=[];summaryData=null;currentCloudId=null;qualityRun=null;$('personalNotes').value='';$('title').value='';attachAudio(null);$('summaryBox').classList.add('hidden');document.querySelector('.assistant-intro').classList.remove('hidden');render();clearTimeout(studioCheckpointTimer);renderReview();renderLibrary()}renderGlossary()}
window.addEventListener('beforeunload',e=>{archiveCurrent();if(active||qualityUploads.size){e.preventDefault();e.returnValue=''}});
syncDock();render();renderReview();renderGlossary();studioAccountChanged();

// Keep deletion scoped to the classroom the user actually confirmed.
deleteCloud=async function(){const id=currentCloudId,user=accountUserId;if(!supabaseClient||!id)return toast('请先打开一堂云端课堂。');if(!confirm('删除当前这堂云端笔记？本机副本与录音不受影响。'))return;const {error}=await supabaseClient.from('lectures').delete().eq('id',id);if(error)return toast('删除失败：'+error.message);if(user===accountUserId){studioCloudRows=studioCloudRows.filter(x=>x.id!==id);if(currentCloudId===id){currentCloudId=null;archiveCurrent()}renderLibrary()}toast('已删除选中的云端课堂。')};$('cloudDelete').onclick=deleteCloud;
document.querySelectorAll('[data-study]').forEach((b,i,buttons)=>b.addEventListener('keydown',e=>{if(e.key!=='ArrowRight'&&e.key!=='ArrowLeft')return;e.preventDefault();const n=(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;showStudy(buttons[n].dataset.study);buttons[n].focus()}));
